PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,avatar_color TEXT NOT NULL);
CREATE TABLE trips(id INTEGER PRIMARY KEY,name TEXT NOT NULL,destination TEXT NOT NULL,country_code TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,timezone TEXT NOT NULL);
CREATE TABLE trip_members(trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','member')),PRIMARY KEY(trip_id,user_id));
CREATE TABLE trip_days(id INTEGER PRIMARY KEY,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,day_number INTEGER NOT NULL,day_date TEXT NOT NULL,title TEXT,UNIQUE(trip_id,day_number),UNIQUE(trip_id,day_date));
CREATE TABLE places(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,name TEXT NOT NULL,category TEXT NOT NULL,address TEXT,map_url TEXT,website_url TEXT,notes TEXT,is_must_visit INTEGER NOT NULL DEFAULT 0 CHECK(is_must_visit IN(0,1)),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE schedule_items(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,trip_day_id INTEGER REFERENCES trip_days(id) ON DELETE CASCADE,place_id INTEGER REFERENCES places(id) ON DELETE SET NULL,title TEXT NOT NULL,start_time TEXT,end_time TEXT,category TEXT NOT NULL,notes TEXT,status TEXT NOT NULL DEFAULT'confirmed' CHECK(status IN('confirmed','candidate')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE checklist_items(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,title TEXT NOT NULL,is_completed INTEGER NOT NULL DEFAULT 0 CHECK(is_completed IN(0,1)),assignee_id INTEGER REFERENCES users(id) ON DELETE SET NULL,due_date TEXT,category TEXT NOT NULL,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reservations(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,title TEXT NOT NULL,type TEXT NOT NULL,reservation_date TEXT,confirmation_number TEXT,link TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,title TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>0),currency TEXT NOT NULL CHECK(currency IN('KRW','PHP')),paid_by INTEGER REFERENCES users(id),expense_date TEXT NOT NULL,category TEXT NOT NULL,notes TEXT,schedule_item_id INTEGER REFERENCES schedule_items(id) ON DELETE SET NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expense_participants(expense_id INTEGER REFERENCES expenses(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id),share_amount REAL NOT NULL CHECK(share_amount>=0),PRIMARY KEY(expense_id,user_id));
CREATE TABLE notes(id INTEGER PRIMARY KEY AUTOINCREMENT,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,author_id INTEGER REFERENCES users(id),content TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_days ON trip_days(trip_id,day_date);CREATE INDEX idx_places ON places(trip_id);CREATE INDEX idx_schedule ON schedule_items(trip_day_id,start_time);CREATE INDEX idx_checklist ON checklist_items(trip_id,is_completed);CREATE INDEX idx_reservations ON reservations(trip_id,reservation_date);CREATE INDEX idx_expenses ON expenses(trip_id,expense_date);CREATE INDEX idx_participants ON expense_participants(user_id);CREATE INDEX idx_notes ON notes(trip_id,created_at);
